import sys, os
from defusedxml.minidom import parse

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

def qn(tag):
    return '{%s}%s' % (W, tag)

def main():
    path = os.path.join('docx_work', 'word', 'document.xml')
    dom = parse(path)
    paras = dom.getElementsByTagName(qn('p'))
    print('total paragraphs:', len(paras))
    for i, p in enumerate(paras):
        pPr = None
        for child in p.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == qn('pPr'):
                pPr = child
                break
        style = ''
        if pPr is not None:
            for child in pPr.childNodes:
                if child.nodeType == child.ELEMENT_NODE and child.tagName == qn('pStyle'):
                    style = child.getAttribute(qn('val'))
                    break
        # collect text
        texts = []
        for t in p.getElementsByTagName(qn('t')):
            texts.append(t.firstChild.data if t.firstChild else '')
        text = ''.join(texts)[:90]
        if style or text.strip():
            print('%4d style=%-12s | %s' % (i, style or '-', text))

if __name__ == '__main__':
    main()

import os
from defusedxml.minidom import parse

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'


def qn(tag):
    return '{%s}%s' % (W, tag)


def para_text(p):
    parts = []
    for t in p.getElementsByTagName(qn('t')):
        if t.firstChild is not None:
            parts.append(t.firstChild.data)
    return ''.join(parts)


def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    if not any(c.isalpha() for c in text):
        return False
    # Headlines in this report are the all-caps section titles
    return text == text.upper()


def main():
    doc_path = os.path.join('docx_work', 'word', 'document.xml')
    dom = parse(doc_path)
    underlined = []
    for p in dom.getElementsByTagName(qn('p')):
        if not is_headline(p):
            continue
        for r in p.getElementsByTagName(qn('r')):
            has_text = False
            for t in r.getElementsByTagName(qn('t')):
                if t.firstChild is not None and t.firstChild.data:
                    has_text = True
            if not has_text:
                continue
            rprs = [c for c in r.childNodes
                    if c.nodeType == c.ELEMENT_NODE and c.tagName == qn('rPr')]
            if rprs:
                rpr = rprs[0]
            else:
                rpr = dom.createElement(qn('rPr'))
                r.insertBefore(rpr, r.firstChild)
            us = [c for c in rpr.childNodes
                  if c.nodeType == c.ELEMENT_NODE and c.tagName == qn('u')]
            if us:
                us[0].setAttribute(qn('val'), 'single')
            else:
                u = dom.createElement(qn('u'))
                u.setAttribute(qn('val'), 'single')
                rpr.appendChild(u)
        underlined.append(para_text(p).strip())
    with open(doc_path, 'w', encoding='utf-8') as f:
        f.write(dom.toprettyxml(indent='  ', encoding='utf-8').decode('utf-8'))
    # Remove inspection scratch file kept inside the docx work tree
    stray = os.path.join('docx_work', 'inspect_headings.py')
    try:
        os.remove(stray)
    except OSError:
        pass
    print('underlined %d headline(s): %s' % (len(underlined), ', '.join(underlined)))


if __name__ == '__main__':
    main()

